func i32x4_trunc_sat_f32x4_s(a v128) (r v128) {
	for i := 0; i < 16; i += 4 {
		f := math.Float32frombits(binary.LittleEndian.Uint32(a[i:]))
		var x int32
		switch {
		case f <= math.MinInt32:
			x = math.MinInt32
		case f >= math.MaxInt32:
			x = math.MaxInt32
		case f != f:
			x = 0
		default:
			x = int32(f)
		}
		binary.LittleEndian.PutUint32(r[i:], uint32(x))
	}
	return
}

